// ============================================================
// Match Snipe User — Manual del desarrollador
// ------------------------------------------------------------
// Propósito:
//   Selecciona el usuario de Snipe-IT que coincide exactamente
//   (case-insensitive) con el email del ticket. Ante duplicados
//   reales en Snipe-IT gana el id menor (mismo criterio que
//   Bulk Save Users, fix 2026-09-03).
//
// Entradas:
//   - $('Extract Ticket').first().json
//       { ticket_id, ticket_number, customer_email }
//   - $input.first().json  (salida de Find Snipe User)
//       { body?: { rows: Array<{id, email}> }, error?: any }
//
// Reglas de negocio:
//   - Comparación exacta LOWER (sin trim extra; Extract Ticket ya hace trim).
//   - Si no hay email, no hay hits.
//   - snipe_error = true solo si !body && !!error (fallo de red/API).
//
// Salida:
//   - Un item: { ticket_id, ticket_number, customer_email,
//                snipe_user_id, snipe_error, match_count }
// ============================================================

// ---------- Config / constantes ----------
const FALLBACK_MAX_ID = 9e15; // id muy grande para ordenar nulos al final

// ---------- Helpers puros ----------
function normalizeEmail(value) {
  return String(value || '').toLowerCase();
}

function isSnipeFetchError(snipeResponse) {
  return !snipeResponse.body && !!snipeResponse.error;
}

function findExactEmailMatches(rows, normalizedEmail) {
  if (!normalizedEmail) return [];
  return rows.filter((row) => normalizeEmail(row.email) === normalizedEmail);
}

function sortByIdAsc(rows) {
  return rows.sort((a, b) => (a.id ?? FALLBACK_MAX_ID) - (b.id ?? FALLBACK_MAX_ID));
}

// ---------- Main ----------
const ticket = $('Extract Ticket').first().json;
const snipeResponse = $input.first().json;

const normalizedTicketEmail = normalizeEmail(ticket.customer_email);
const candidateRows = snipeResponse.body?.rows || [];
const isError = isSnipeFetchError(snipeResponse);

const hits = sortByIdAsc(findExactEmailMatches(candidateRows, normalizedTicketEmail));
const bestMatch = hits[0] || null;

return [{
  json: {
    ticket_id: ticket.ticket_id,
    ticket_number: ticket.ticket_number,
    customer_email: ticket.customer_email,
    snipe_user_id: bestMatch ? bestMatch.id : null,
    snipe_error: isError,
    match_count: hits.length,
  },
}];

// ============================================================
// Build Enrichment — Manual del desarrollador
// ------------------------------------------------------------
// Propósito:
//   Construye el contrato final de enriquecimiento del ticket:
//   conteo, tags, resumen UX y nota interna a partir de los
//   activos asignados en Snipe-IT.
//
// Entradas:
//   - $('Extract Ticket').first().json
//       { ticket_id, ticket_number, customer_email }
//   - $('Match Snipe User').first().json
//       { snipe_user_id }
//   - $input.first().json  (salida de Get Assigned Assets)
//       { body?: { rows: Array<Asset> }, error?: any }
//       Asset = { asset_tag, model?:{name}, category?:{name},
//                 status_label?:{name}, status?:{name}, serial }
//
// Reglas de negocio / contrato UX (2026-09-14, 5 líneas reales):
//   - Si !body => error de red/API => summary vacío, nota de error.
//   - Si 0 activos => summary vacío, nota "sin activos".
//   - Si N>0 => summary = bloque UX:
//       ACTIVOS SNIPE-IT (N)
//       --------------------
//       01 <modelo>
//          <categoría>
//          <tag>
//          <estado>
//          S/N <serial>
//       (blank line entre activos, orden por asset_tag, una línea
//        por dato sin etiquetas largas, valores reales Snipe-IT
//        sin conversión OK/MAL, fallbacks Modelo?/Categoría?/Estado?/s/n)
//   - asset_tags = tags unidos por ", " en el mismo orden.
//   - note_body = mismo bloque que summary cuando N>0.
//
// Salida:
//   - Un item: { ticket_id, ticket_number, customer_email,
//                snipe_user_id, asset_count, asset_tags,
//                asset_summary, note_body }
// ============================================================

// ---------- Config / constantes ----------
const MSG_FETCH_ERROR = 'No se pudo consultar los activos en Snipe-IT (error de red/API).';
const MSG_NO_ASSETS = 'Snipe-IT no reporta activos asignados a este usuario.';
const FALLBACK_MODEL = 'Modelo?';
const FALLBACK_CATEGORY = 'Categoría?';
const FALLBACK_STATUS = 'Estado?';
const FALLBACK_TAG = 's/n';
const FALLBACK_SERIAL = 's/n';

// ---------- Helpers puros (arrow) ----------
const isFetchError = (response) => !response.body;
const sortByAssetTag = (rows) => [...rows].sort((a, b) => String(a.asset_tag || '').localeCompare(String(b.asset_tag || '')));
const formatAssetBlock = (asset, index) => {
  const model = asset.model?.name || FALLBACK_MODEL;
  const category = asset.category?.name || FALLBACK_CATEGORY;
  const tag = asset.asset_tag || FALLBACK_TAG;
  const status = asset.status_label?.name || asset.status?.name || FALLBACK_STATUS;
  const serial = asset.serial || FALLBACK_SERIAL;
  const paddedIndex = String(index + 1).padStart(2, '0');
  return `${paddedIndex} ${model}\n   ${category}\n   ${tag}\n   ${status}\n   S/N ${serial}`;
};
const buildSummaryBlock = (sortedRows) => {
  const count = sortedRows.length;
  if (count === 0) return { summary: '', note: MSG_NO_ASSETS, count, tags: '' };
  const header = `ACTIVOS SNIPE-IT (${count})\n--------------------`;
  const blocks = sortedRows.map((row, i) => formatAssetBlock(row, i)).join('\n\n');
  const summary = `${header}\n${blocks}`;
  return { summary, note: summary, count, tags: sortedRows.map((r) => r.asset_tag).join(', ') };
};

// ---------- Main ----------
const ticket = $('Extract Ticket').first().json;
const matchedUser = $('Match Snipe User').first().json;
const snipeResponse = $input.first().json;
const hasFetchError = isFetchError(snipeResponse);

let assetSummary = '';
let noteBody = '';
let assetCount = 0;
let assetTags = '';

if (hasFetchError) {
  assetSummary = '';
  noteBody = MSG_FETCH_ERROR;
} else {
  const sortedRows = sortByAssetTag(snipeResponse.body?.rows || []);
  const built = buildSummaryBlock(sortedRows);
  assetSummary = built.summary;
  noteBody = built.note;
  assetCount = built.count;
  assetTags = sortedRows.map((r) => r.asset_tag).join(', ');
}

return [{
  json: {
    ticket_id: ticket.ticket_id,
    ticket_number: ticket.ticket_number,
    customer_email: ticket.customer_email,
    snipe_user_id: matchedUser.snipe_user_id,
    asset_count: assetCount,
    asset_tags: assetTags,
    asset_summary: assetSummary,
    note_body: noteBody,
  },
}];

// ============================================================
// Build Empty (no user) — Manual del desarrollador
// ------------------------------------------------------------
// Propósito:
//   Produce el contrato vacío cuando Snipe-IT no tiene usuario
//   con ese email o la consulta de usuarios falló. Converge con
//   las otras dos ramas (Build Enrichment / Build Empty no email)
//   hacia Update Zammad Ticket con el mismo contrato.
//
// Entrada:
//   - $('Match Snipe User').first().json
//       { ticket_id, ticket_number, customer_email,
//         snipe_error: boolean }
//
// Reglas:
//   - Si snipe_error => nota de error de red/API (reintentar).
//   - Si no => nota "no tiene usuario con email X".
//   - Siempre: snipe_user_id=null, count=0, tags/summary vacíos.
//
// Salida:
//   - Un item con el contrato vacío + note_body diferenciada.
// ============================================================

// ---------- Config / constantes ----------
const MSG_SNIPE_FETCH_ERROR = 'No se pudo consultar Snipe-IT (error de red/API); reintentar manualmente.';

function buildMissingUserNote(customerEmail) {
  return `Snipe-IT no tiene usuario con email ${customerEmail}.`;
}

// ---------- Main ----------
const matchedUser = $('Match Snipe User').first().json;

const noteBody = matchedUser.snipe_error
  ? MSG_SNIPE_FETCH_ERROR
  : buildMissingUserNote(matchedUser.customer_email);

return [{
  json: {
    ticket_id: matchedUser.ticket_id,
    ticket_number: matchedUser.ticket_number,
    customer_email: matchedUser.customer_email,
    snipe_user_id: null,
    asset_count: 0,
    asset_tags: '',
    asset_summary: '',
    note_body: noteBody,
  },
}];

